//! Acceptance criteria of #4: `examples/hello/hello.S` assembles with
//! merlin-as into the same object clang makes of it with `-mno-relax`.
//!
//! Two committed references, both regenerated by `scripts/gen-hello-ref.sh`
//! (clang and llvm-objdump), so these tests need no LLVM:
//!
//! * `tests/golden/hello.ref`: every word of clang's `.text.start` and the
//!   relocation on it. Ours must be identical: same words (the labels clang
//!   resolves, merlin-as resolves too) and the same relocations.
//! * `tests/golden/hello.dr.txt`: `llvm-objdump -dr` of clang's object. The
//!   disassembly of ours by merlin-objdump (which prints what llvm-objdump 21
//!   prints) must be the same text, labels and relocations included.
//!
//! Linking the result with ld.lld and running it in Grail is checked by
//! `crates/xtask/tests/hello.rs`.

use merlin_as::Object;

const SOURCE: &str = include_str!("../../../examples/hello/hello.S");
const SECTION: &str = ".text.start";

fn assemble() -> Object {
    match merlin_as::assemble(SOURCE) {
        Ok(o) => o,
        Err(errs) => {
            let lines: Vec<&str> = SOURCE.lines().collect();
            let shown: Vec<String> = errs
                .iter()
                .map(|e| {
                    let src = e.line.checked_sub(1).and_then(|i| lines.get(i)).unwrap_or(&"");
                    format!("  {e}\n      {}", src.trim())
                })
                .collect();
            panic!("hello.S does not assemble:\n{}", shown.join("\n"));
        }
    }
}

/// One word of clang's `.text.start`, as in hello.ref:
/// `<hex offset> <word> [<R_RISCV_TYPE> <symbol or <auipc>>[+hexaddend]]`.
fn reference() -> Vec<String> {
    include_str!("golden/hello.ref")
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| l.split_whitespace().collect::<Vec<_>>().join(" "))
        .collect()
}

/// Our `.text.start` in hello.ref's format.
fn ours(obj: &Object) -> Vec<String> {
    let text = obj
        .sections
        .iter()
        .find(|s| s.name == SECTION)
        .unwrap_or_else(|| panic!("no {SECTION} section"));
    text.data
        .chunks(4)
        .enumerate()
        .map(|(n, c)| {
            let off = 4 * n as u32;
            let word = u32::from_le_bytes([c[0], c[1], c[2], c[3]]);
            let mut line = format!("{off:x} {word:08x}");
            if let Some(r) = text.relocs.iter().find(|r| r.offset == off) {
                // The hidden label of a pc-relative pair: clang calls it
                // .Lpcrel_hiN too, but the reference doesn't depend on N.
                let sym = if r.symbol.starts_with(".Lpcrel_hi") {
                    "<auipc>"
                } else {
                    &r.symbol
                };
                line += &format!(" {} {sym}", r.kind.name());
                if r.addend != 0 {
                    line += &format!("+{:x}", r.addend);
                }
            }
            line
        })
        .collect()
}

#[test]
fn reference_is_well_formed() {
    let refs = reference();
    assert_eq!(refs.len(), 20);
    // hello.S's first instruction is `la sp, __stack_top`.
    assert_eq!(refs[0], "0 00000117 R_RISCV_PCREL_HI20 __stack_top");
}

#[test]
fn hello_matches_clang() {
    let obj = assemble();
    let (ours, refs) = (ours(&obj), reference());
    let diffs: Vec<String> = (0..ours.len().max(refs.len()))
        .filter_map(|i| {
            let (a, b) = (ours.get(i), refs.get(i));
            (a != b).then(|| {
                format!(
                    "ours:  {}\n  clang: {}",
                    a.map_or("-", |s| s),
                    b.map_or("-", |s| s)
                )
            })
        })
        .collect();
    assert!(
        diffs.is_empty(),
        "{SECTION} differs from clang:\n  {}",
        diffs.join("\n  ")
    );
}

#[test]
fn hello_disassembles_like_clang() {
    let elf = merlin_as::elf::write(&assemble());
    let opts = merlin_objdump::Options {
        disassemble: true,
        relocs: true,
        ..merlin_objdump::Options::default()
    };
    let ours = merlin_objdump::dump("hello.o", &elf, &opts).unwrap();
    // The one deliberate difference between merlin-objdump and llvm-objdump
    // here (spec section 10): LLVM doesn't know the Xcal instructions.
    let ours: Vec<String> = ours
        .lines()
        .map(|l| match l.split_once("\txcal.") {
            Some((head, _)) => format!("{head}\t<unknown>"),
            None => l.to_string(),
        })
        .collect();
    let want: Vec<&str> = include_str!("golden/hello.dr.txt").lines().collect();
    assert_eq!(ours, want);
}
